def base_path(main_path, fmt, formats=None):
    fmt = long_form_one_format(fmt)
    base, ext = os.path.splitext(main_path)
    if 'extension' not in fmt:
        fmt['extension'] = ext
        if ext not in NOTEBOOK_EXTENSIONS:
            raise InconsistentPath("'{}' is not a notebook. Supported extensions are '{}'.".format(main_path, "', '".join(NOTEBOOK_EXTENSIONS)))
    if ext != fmt['extension']:
        raise InconsistentPath("Notebook path '{}' was expected to have extension '{}'".format(main_path, fmt['extension']))
    if formats is None:
        formats = [fmt]
    for f in formats:
        if 'extension' in f and f['extension'] != fmt['extension']:
            continue
        if 'suffix' in f and f['suffix'] != fmt['suffix']:
            continue
        if 'prefix' in f and f['prefix'] != fmt['prefix']:
            continue
        fmt = {key: fmt.get(key, f.get(key)) for key in fmt}
        break
    suffix = fmt.get('suffix')
    prefix = fmt.get('prefix')
    if suffix:
        if not base.endswith(suffix):
            raise InconsistentPath("Notebook name '{}' was expected to end with suffix '{}'".format(base, suffix))
        base = base[:-len(suffix)]
    if not prefix:
        return base
    if '//' in prefix:
        prefix_root, prefix = prefix.rsplit('//', 1)
    else:
        prefix_root = ''
    sep = separator(base)
    notebook_dir, notebook_file_name = split(base, sep)
    prefix_dir, prefix_file_name = split(prefix, '/')
    if prefix_dir:
        if not notebook_file_name.startswith(prefix_file_name):
            raise InconsistentPath("Notebook name '{}' was expected to start with prefix '{}'".format(notebook_file_name, prefix_file_name))
        notebook_file_name = notebook_file_name[len(prefix_file_name):]
    if prefix_root:
        if notebook_dir != prefix_root:
            raise InconsistentPath("Notebook directory '{}' was expected to be '{}'".format(notebook_dir, prefix_root))
    if notebook_dir:
        return notebook_dir + sep + notebook_file_name
    return notebook_file_name
